+		return err
+	}
+	g.decryptInfo = &decryptInfo{
+		cipherDir: filepath.Join(tmpDir, "cipher"),
+		plainDir:  filepath.Join(tmpDir, "plain"),
+		pass:      "",
+		confPath:  filepath.Join(filepath.Join(tmpDir, "cipher"), "gocryptfs.conf"),
+	}
