+		return os.RemoveAll(tmpDir)
+	}
+
+	err = os.Mkdir(g.decryptInfo.cipherDir, 0o700)
+	if err != nil {
+		return err
+	}
+	err = os.Mkdir(g.decryptInfo.plainDir, 0o700)
